  #crosshair i:nth-child(1) { width: 2px; height: 7px; left: -1px; top: calc(-1 * var(--spread) - 7px); }
  #crosshair i:nth-child(2) { width: 2px; height: 7px; left: -1px; top: var(--spread); }
  #crosshair i:nth-child(3) { height: 2px; width: 7px; top: -1px; left: calc(-1 * var(--spread) - 7px); }
  #crosshair i:nth-child(4) { height: 2px; width: 7px; top: -1px; left: var(--spread); }
  #crosshair b { position: absolute; width: 2px; height: 2px; left: -1px; top: -1px; background: var(--ink); }

  #hitmarker { position: fixed; left: 50%; top: 50%; width: 0; height: 0; opacity: 0; transition: opacity 80ms linear; }
