  #overlay {
    position: fixed; inset: 0; display: grid; place-items: center; padding: 24px;
    background: var(--canvas); background: color-mix(in srgb, var(--canvas) 82%, transparent);
    pointer-events: auto;
  }
  #overlay[hidden] { display: none; }
  .panel {
    width: min(480px, 100%);
    padding: 32px;
    background: var(--surface);
    border: 1px solid var(--hairline);
  }
  .panel h1 {
    margin: 0 0 10px; font-size: 46px; line-height: 1; font-weight: 600; letter-spacing: -.01em;
  }
  .panel p { margin: 0 0 22px; max-width: 48ch; font-size: 15px; line-height: 1.5; color: var(--muted); }
