  if (!item.solid) continue;
  COLLIDERS.push({
    minX: item.x - item.w / 2,
    maxX: item.x + item.w / 2,
    minY: item.y,
    maxY: item.y + item.h,
    minZ: item.z - item.d / 2,
    maxZ: item.z + item.d / 2,
  });
}
for (const item of CYLINDERS) {
  if (!item.solid) continue;
  const half = item.r * 0.86;
  COLLIDERS.push({
    minX: item.x - half,
    maxX: item.x + half,
    minY: 0,
    maxY: item.h,
    minZ: item.z - half,
    maxZ: item.z + half,
  });
}

export function siteAt(x, z) {
  for (const site of SITES) {
    if (x >= site.minX && x <= site.maxX && z >= site.minZ && z <= site.maxZ) return site;
  }
  return null;
}

export function siteById(id) {
  return SITES.find((site) => site.id === id) ?? SITES[0];
}

// The floor is at y = 0 and every spawn stands on it.
export function spawnFor(team, index) {
  const list = SPAWNS[team];
  return list[index % list.length];
}
