// A small seeded generator (mulberry32) so a round's spread, bot choices and screenshot setups
// replay exactly. One instance lives on the simulation; nothing else calls Math.random.
export function createRng(seed) {
  let a = seed >>> 0;
  return function random() {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
