}

function aimAt(bot, target, dt) {
  const ai = bot.ai;
  const chest = chestOf(target);
  const dx = chest.x - bot.body.pos.x;
  const dz = chest.z - bot.body.pos.z;
  const dy = chest.y - eyeY(bot);
  const distance = Math.hypot(dx, dz);
